window.__rgjR=null; window.__rgjErr=null;
(async () => { try {
  const want = ["The Legend of Zelda", "Zelda II: The Adventure of Link", "Metroid", "StarTropics", "The Goonies II", "Battle of Olympus", "Clash at Demonhead", "Kid Icarus", "Simon's Quest", "Monster Party", "Xexyz", "Goonies"];
  const alnum = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g,'');
  const toks  = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().split(' ').filter(Boolean);
  const findAch = (n,d) => { if(!n||typeof n!=='object'||d>8) return null;
    if (Array.isArray(n)&&n.length&&n[0]&&typeof n[0]==='object'&&'title' in n[0]&&'points' in n[0]) return n;
    for (const k in n){ const r=findAch(n[k],d+1); if(r) return r; } return null; };
  const pick = (rows) => {
    const r = rows.filter(a => Number(a.points) > 0)
                  .sort((a,b)=> a.ratio-b.ratio || a.points-b.points || a.id-b.id);
    if (!r.length) return [];
    if (r.length <= 3) return r.map((x,i)=>({...x, tier:['easy','intermediate','advanced'][i]}));
    const easy=r[0], hard=r[r.length-1];
    const mid=Math.sqrt(Math.max(easy.ratio,1)*Math.max(hard.ratio,1));
    const dist=x=>Math.abs(Math.log(Math.max(x.ratio,1))-Math.log(mid));
    let m=r[1]; for (const x of r.slice(1,-1)) if (dist(x)<dist(m)) m=x;
    return [{...easy,tier:'easy'},{...m,tier:'intermediate'},{...hard,tier:'advanced'}];
  };
  const score = (a, b) => {
    if (alnum(a) === alnum(b)) return 100;
    const ta = toks(a), tb = toks(b);
    const hit = ta.filter(x => tb.includes(x)).length;
    const cand = alnum(b), q = alnum(a);
    let s = hit * 10;
    if (cand.startsWith(q) || q.startsWith(cand)) s += 8;
    if (cand.includes(q) && q.length > 4) s += 6 - (cand.length - q.length) / 20;
    return s - Math.abs(ta.length - tb.length);
  };
  const out = {};
  for (const t of want) {
    let games = [];
    for (const q of [t, t.replace(/[^A-Za-z0-9 ]+/g,' ')]) {
      try {
        const j = await (await fetch('https://retroachievements.org/internal-api/search?q='+encodeURIComponent(q)+'&scope=games')).json();
        games = games.concat((j.results && j.results.games) || []);
      } catch(e) {}
      await new Promise(r=>setTimeout(r,120));
    }
    const seen = new Map();
    for (const g of games) if (g.system && g.system.id === 7 && !seen.has(g.id)) seen.set(g.id, g);
    let best = null, bestScore = 0;
    for (const g of seen.values()) { const s = score(t, g.title); if (s > bestScore) { bestScore = s; best = g; } }
    if (!best || bestScore < 12) { out[t] = { unmatched: true, near: [...seen.values()].map(g=>g.title).slice(0,6) }; continue; }
    try {
      const h = await (await fetch('https://retroachievements.org/game/'+best.id)).text();
      const d2 = new DOMParser().parseFromString(h,'text/html');
      const j2 = JSON.parse(d2.querySelector('script[type="application/json"]').textContent);
      const arr = findAch(j2,0) || [];
      const rows = arr.map(a => ({ id:a.id, title:a.title, desc:a.description||'', points:Number(a.points)||0,
                                   ratio:Number(a.pointsWeighted)||Number(a.points)||0, type:a.type||'' }));
      out[t] = { raId: best.id, raTitle: best.title, n: rows.length, matchScore: bestScore, picks: pick(rows), unmatched: false };
    } catch(e) { out[t] = { raId: best.id, raTitle: best.title, error: String(e.message), picks: [] }; }
    await new Promise(r=>setTimeout(r,120));
  }
  window.__rgjR = JSON.stringify(out);
} catch(e){ window.__rgjErr = String(e && e.stack || e); } })();
